#!/usr/bin/env python3
import sys, re
sys.path.insert(0,'/workspace/probe')
from screen import Screen

class Scr(Screen):
    def __init__(self, cols, rows):
        super().__init__(cols, rows)
        self.fg = None; self.flags = set()
    def handle_csi(self, esc):
        m = re.match(r'\[([0-9;?]*)([A-Za-z@`~])$', esc)
        if m and m.group(2) == 'm' and '?' not in m.group(1):
            nums = [int(x) if x else 0 for x in m.group(1).split(';')] or [0]
            for n in nums:
                if n == 0: self.flags.clear(); self.fg = None
                elif n == 22: self.flags.discard(1); self.flags.discard(2)
                elif n == 24: self.flags.discard(4)
                elif n == 27: self.flags.discard(7)
                elif n == 39: self.fg = None
                elif 30 <= n <= 37 or 90 <= n <= 97: self.fg = n
                else: self.flags.add(n)
            self.cur_attr = sorted(self.flags) + ([self.fg] if self.fg else [])
        else:
            super().handle_csi(esc)

def load(path, cols=150, rows=50):
    s = Scr(cols, rows); s.feed(open(path,'rb').read()); return s

if __name__ == '__main__':
    s = load(sys.argv[1])
    for y in range(s.rows):
        x = 0
        while x < s.cols:
            a = s.attrs[y][x]
            if not a: x += 1; continue
            x0 = x
            while x < s.cols and s.attrs[y][x] == a: x += 1
            txt = ''.join(s.buf[y][x0:x])
            if txt.strip():
                print(f"r{y:02d} c{x0:03d} {a} {txt!r}")
